namespace OneIndex.Vectors;

/// <summary>Which side of a retrieval pair a text is. Some models embed queries differently from documents (for example with an
/// instruction prefix on the query), so the caller says which it is passing.</summary>
public enum EmbeddingRole
{
    /// <summary>A text that will be stored and searched (a passage, a title, a chunk).</summary>
    Document = 0,

    /// <summary>A text typed or generated by a searcher, used to look documents up.</summary>
    Query = 1,
}

/// <summary>
/// Turns text into dense float vectors of one fixed dimension.
/// </summary>
/// <remarks>
/// <para>Implementations are thread-safe: any number of callers may embed at once. Embedding is deterministic for a given
/// <see cref="ModelId"/>, so a vector may be cached under (<see cref="ModelId"/>, role, text).</para>
/// <para>Vectors are written in caller-provided memory, one row of <see cref="Dimension"/> floats per text, in input order. The
/// destination must hold exactly <c>texts.Count * Dimension</c> floats. Texts longer than the model's input limit are truncated, never rejected. The empty string
/// is a valid text. A <see langword="null"/> text throws <see cref="ArgumentNullException"/>.</para>
/// <para>The sparse, multi-vector and reranking contracts are siblings of this one: same shape, same rules.</para>
/// </remarks>
public interface IEmbedder
{
    /// <summary>A stable identity of the model and every setting that changes its output (weights, quantization, prefix,
    /// truncation length), for example <c>bge-small-en-v1.5/int8</c>. Two embedders with the same identity produce the same
    /// vectors for the same text and role, so it is safe as part of an embedding cache key. Never empty.</summary>
    string ModelId { get; }

    /// <summary>The length of every vector this embedder produces. Positive and constant for the embedder's life.</summary>
    int Dimension { get; }

    /// <summary>Whether every vector has unit length, so that the dot product equals cosine similarity and may be used as the
    /// distance.</summary>
    bool IsNormalized { get; }

    /// <summary>Embeds a batch of texts.</summary>
    /// <param name="texts">The texts to embed; none may be <see langword="null"/>. An empty list does nothing.</param>
    /// <param name="role">Whether the texts are documents or queries.</param>
    /// <param name="destination">Receives <c>texts.Count * Dimension</c> floats, row-major.</param>
    /// <param name="cancellationToken">Observed between model runs; a cancelled call may leave the destination partly written.</param>
    /// <exception cref="ArgumentException"><paramref name="destination"/> is not exactly the required length.</exception>
    /// <exception cref="ArgumentNullException">A text is <see langword="null"/>.</exception>
    /// <exception cref="OperationCanceledException">The token was cancelled.</exception>
    void Embed(IReadOnlyList<string> texts, EmbeddingRole role, Span<float> destination, CancellationToken cancellationToken = default);

    /// <summary>The asynchronous twin of <see cref="Embed"/>. It yields the thread while the model runs on a pooled thread where
    /// threads exist, and completes cooperatively where they do not; results are identical.</summary>
    /// <param name="texts">The texts to embed.</param>
    /// <param name="role">Whether the texts are documents or queries.</param>
    /// <param name="destination">Receives <c>texts.Count * Dimension</c> floats; it must stay valid until the task completes.</param>
    /// <param name="cancellationToken">Observed between model runs.</param>
    ValueTask EmbedAsync(IReadOnlyList<string> texts, EmbeddingRole role, Memory<float> destination, CancellationToken cancellationToken = default);
}

/// <summary>Convenience overloads for <see cref="IEmbedder"/>.</summary>
public static class EmbedderExtensions
{
    /// <summary>Embeds one text and returns its vector as a new array of <see cref="IEmbedder.Dimension"/> floats.</summary>
    /// <param name="embedder">The embedder.</param>
    /// <param name="text">The text.</param>
    /// <param name="role">Document by default.</param>
    /// <param name="cancellationToken">Observed while the model runs.</param>
    /// <returns>A new vector.</returns>
    public static float[] Embed(this IEmbedder embedder, string text, EmbeddingRole role = EmbeddingRole.Document, CancellationToken cancellationToken = default)
    {
        ArgumentNullException.ThrowIfNull(embedder);
        ArgumentNullException.ThrowIfNull(text);
        var vector = new float[embedder.Dimension];
        embedder.Embed([text], role, vector, cancellationToken);
        return vector;
    }

    /// <summary>Embeds a batch and returns the vectors as one new row-major array of <c>texts.Count * Dimension</c> floats.</summary>
    /// <param name="embedder">The embedder.</param>
    /// <param name="texts">The texts.</param>
    /// <param name="role">Document by default.</param>
    /// <param name="cancellationToken">Observed while the model runs.</param>
    /// <returns>A new row-major array.</returns>
    public static float[] EmbedBatch(this IEmbedder embedder, IReadOnlyList<string> texts, EmbeddingRole role = EmbeddingRole.Document, CancellationToken cancellationToken = default)
    {
        ArgumentNullException.ThrowIfNull(embedder);
        ArgumentNullException.ThrowIfNull(texts);
        var vectors = new float[checked(texts.Count * embedder.Dimension)];
        embedder.Embed(texts, role, vectors, cancellationToken);
        return vectors;
    }

    /// <summary>The asynchronous twin of <see cref="Embed(IEmbedder, string, EmbeddingRole, CancellationToken)"/>.</summary>
    /// <param name="embedder">The embedder.</param>
    /// <param name="text">The text.</param>
    /// <param name="role">Document by default.</param>
    /// <param name="cancellationToken">Observed while the model runs.</param>
    /// <returns>A new vector.</returns>
    public static async ValueTask<float[]> EmbedAsync(this IEmbedder embedder, string text, EmbeddingRole role = EmbeddingRole.Document, CancellationToken cancellationToken = default)
    {
        ArgumentNullException.ThrowIfNull(embedder);
        ArgumentNullException.ThrowIfNull(text);
        var vector = new float[embedder.Dimension];
        await embedder.EmbedAsync([text], role, vector, cancellationToken).ConfigureAwait(false);
        return vector;
    }
}
